params.fn:
function(){
  var body=(document.body&&document.body.innerText)||'';
  var needles=['请完成下方验证','当前访问环境存在异常','操作频繁','扫码登录','验证码','禁止发笔记','违反','账号异常'];
  var hits=[];
  for(var i=0;i<needles.length;i++){
    if(body.indexOf(needles[i])>=0){hits.push(needles[i]);}
  }
  var captcha=!!document.querySelector('.captcha-container,[class*="captcha"]');
  var loginMask=!!document.querySelector('.login-container,[class*="login-mask"]');
  var level='low';
  if(captcha||hits.indexOf('当前访问环境存在异常')>=0||hits.indexOf('请完成下方验证')>=0){level='high';}
  else if(hits.indexOf('操作频繁')>=0||loginMask){level='medium';}
  return {
    risk_level:level,
    captcha_visible:captcha,
    login_mask_visible:loginMask,
    matched_texts:hits,
    page_url:location.href
  };
}
